// Arma el reporte de observabilidad: qué recibió el agente, qué herramientas usó y qué respondió.
const r = $input.first().json;
const entrada = $('Chat de entrada').first().json;
const pasos = r.intermediateSteps || [];
const MAX_ITER = 8;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const severidad = (String(r.output).match(/\bP[1-4]\b/) || ['Sin clasificar'])[0];
const registro = pasos.some((p) => p.action && p.action.tool && !String(p.observation).startsWith('Error'));

const filas = pasos.map((p, i) => `<tr>
  <td style="padding:6px;border:1px solid #ddd">${i + 1}</td>
  <td style="padding:6px;border:1px solid #ddd">${esc(p.action?.tool)}</td>
  <td style="padding:6px;border:1px solid #ddd"><pre style="margin:0;white-space:pre-wrap">${esc(JSON.stringify(p.action?.toolInput, null, 2))}</pre></td>
  <td style="padding:6px;border:1px solid #ddd"><pre style="margin:0;white-space:pre-wrap">${esc(String(typeof p.observation === 'string' ? p.observation : JSON.stringify(p.observation)).slice(0, 2000))}</pre></td>
</tr>`).join('');

const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#211F2E">
<h2 style="margin:0 0 8px">SYNOC · Reporte de ejecución del Agente de Triaje</h2>
<p><b>Ejecución:</b> ${$execution.id} · <b>Sesión:</b> ${esc(entrada.sessionId)} · <b>Fecha:</b> ${$now.toFormat('yyyy-MM-dd HH:mm:ss')}</p>
<p><b>Severidad detectada:</b> ${severidad} · <b>Herramienta usada:</b> ${registro ? 'Sí' : 'No'} · <b>Iteraciones:</b> ${pasos.length} de ${MAX_ITER} permitidas</p>
<h3>Mensaje recibido</h3><blockquote style="border-left:3px solid #7C3BED;margin:0;padding:4px 10px">${esc(entrada.chatInput)}</blockquote>
<h3>Recorrido del agente (Execution Log)</h3>
${pasos.length ? `<table style="border-collapse:collapse;width:100%"><tr style="background:#EDE2F8"><th>#</th><th>Herramienta</th><th>Entrada</th><th>Resultado</th></tr>${filas}</table>` : '<p>El agente respondió sin usar herramientas.</p>'}
<h3>Respuesta entregada</h3><pre style="white-space:pre-wrap;background:#F6F6F9;padding:10px">${esc(r.output)}</pre>
<p style="color:#888;font-size:12px">Reporte automático de supervisión humana · Checkpoint 1</p></div>`;

return [{ json: {
  asunto: `[SYNOC Triaje] ${severidad} · ${registro ? 'Incidente registrado' : 'Sin registro'} · Ejecución ${$execution.id}`,
  html,
  severidad,
  herramienta_usada: registro,
  iteraciones: pasos.length,
} }];
